// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {OwnableRoles} from "solady/auth/OwnableRoles.sol";
import {ReentrancyGuard} from "solady/utils/ReentrancyGuard.sol";
import {UUPSUpgradeable} from "solady/utils/UUPSUpgradeable.sol";
import {Initializable} from "solady/utils/Initializable.sol";
import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";
import {SafeCastLib} from "solady/utils/SafeCastLib.sol";
import {LibCurve} from "./libraries/LibCurve.sol";
import {ITeamMarket} from "./interfaces/ITeamMarket.sol";
import {IFeeRouter} from "./interfaces/IFeeRouter.sol";
import {IRewardsVault} from "./interfaces/IRewardsVault.sol";

/// @title TeamMarket
/// @notice SINGLETON registry of virtual-reserve constant-product bonding
///         pools — one per nation/team token, all quoted in CUP.
///
///         Solvency model: `realCup` only ever grows from CUP the pool
///         actually received (buys + donations) and only ever shrinks by
///         CUP it pays out on sells (solvency-gated `gross <= realCup`) or
///         by owner-directed post-elimination recycling. Every shrink is
///         paired with an actual CUP transfer out.
///         Invariant: cup.balanceOf(market) == Σ pools.realCup.
///
///         Fees: buy 2% / sell 7% initial, owner-tunable under
///         MAX_FEE_BPS = 1000 (anti-rug ceiling). Fees route through the
///         FeeRouter (MARKET_BUY / MARKET_SELL routes). The MARKET_SELL
///         route's POOL_DONATE leg re-enters {donateCup} mid-sell — that
///         re-entry is deliberate and safe (donate only ADDS reserves and
///         is therefore NOT nonReentrant; see {donateCup}).
///
///         Pause blocks swaps, never views; donations stay open so reward
///         seeding and fee recycling cannot brick.
///         UUPS-UPGRADEABLE + MUTABLE $CUP: `cup` is storage (not immutable)
///         set in {initialize} (may start as address(0)) and re-settable once by
///         the owner via {setCupToken} — so the protocol can deploy BEFORE the
///         Moonit launchpad mints $CUP. Every value-moving swap reverts
///         {CupNotSet} until the address is wired.
contract TeamMarket is OwnableRoles, ReentrancyGuard, UUPSUpgradeable, Initializable, ITeamMarket {
    using SafeCastLib for uint256;

    uint256 public constant OPERATOR_ROLE = _ROLE_0;
    /// @notice Granted to the TeamTokenFactory — sole pool creator.
    uint256 public constant FACTORY_ROLE = _ROLE_1;

    /// @notice Anti-rug fee ceiling (10%).
    uint16 public constant MAX_FEE_BPS = 1_000;

    /// @notice FeeRouter route ids.
    bytes32 public constant MARKET_BUY = keccak256("MARKET_BUY");
    bytes32 public constant MARKET_SELL = keccak256("MARKET_SELL");

    /// @notice The CUP quote token. STORAGE (not immutable) so it can be wired
    ///         after the Moonit launch via {setCupToken}; zero until then.
    address public cup;

    /// @notice Fee router receiving swap fees.
    IFeeRouter public feeRouter;

    /// @notice Buy fee in bps (initial 200 = 2%; set in {initialize} — inline
    ///         initializers do not apply to a proxy's storage).
    uint16 public buyFeeBps;

    /// @notice Sell fee in bps (initial 700 = 7%; set in {initialize}).
    uint16 public sellFeeBps;

    /// @notice Pause flag — blocks buy/sell, never views/donations/claims.
    bool public paused;

    /// @notice teamId → pool.
    mapping(bytes32 => Pool) private _pools;

    event PoolCreated(bytes32 indexed teamId, address indexed token, uint8 tier, uint128 virtualCup, uint256 seededTok);
    event Bought(
        bytes32 indexed teamId, address indexed buyer, uint256 cupIn, uint256 fee, uint256 tokensOut, uint256 spotAfter
    );
    event Sold(
        bytes32 indexed teamId, address indexed seller, uint256 tokensIn, uint256 fee, uint256 cupOut, uint256 spotAfter
    );
    event CupDonated(bytes32 indexed teamId, address indexed donor, uint256 amount);
    event PoolCupRecycled(bytes32 indexed teamId, address indexed to, uint256 amount);
    event PoolCupRecycledToTeamPool(bytes32 indexed teamId, address indexed rewardsVault, uint256 amount);
    event FeesSet(uint16 buyFeeBps, uint16 sellFeeBps);
    event FeeRouterSet(address indexed feeRouter);
    event PausedSet(bool paused);
    event PoolActiveSet(bytes32 indexed teamId, bool active);
    event CupTokenSet(address indexed cup);

    error ZeroAddress();
    error PoolExists();
    error PoolMissing();
    error PoolInactive();
    error MarketPaused();
    error FeeTooHigh();
    error DeadlinePassed();
    error SlippageExceeded();
    error ZeroAmount();
    error CupNotSet();
    error InsufficientPoolCup();

    /// @notice Disables initializers on the implementation (proxy-only init).
    constructor() {
        _disableInitializers();
    }

    /// @notice One-shot proxy initialiser.
    /// @param _owner Owner (transfer to a TIMELOCK+MULTISIG before mainnet).
    /// @param _cup   CUP token — MAY be address(0) at init (Moonit launch is
    ///               token-after-deploy); wire it later via {setCupToken}.
    function initialize(address _owner, address _cup) public initializer {
        if (_owner == address(0)) revert ZeroAddress();
        _initializeOwner(_owner);
        cup = _cup;
        // Spec-locked default fees (inline initializers do NOT apply to a proxy).
        buyFeeBps = 200; // 2%
        sellFeeBps = 700; // 7%
        if (_cup != address(0)) emit CupTokenSet(_cup);
    }

    /// @notice Owner-only one-time wiring (or re-wiring) of the $CUP token.
    ///         If a fee router is already configured, re-grants it the standing
    ///         max-approval to pull swap fees in the new token. NOTE: ownership
    ///         must move to a TIMELOCK+MULTISIG before mainnet.
    function setCupToken(address _cup) external onlyOwner {
        if (_cup == address(0)) revert ZeroAddress();
        cup = _cup;
        if (address(feeRouter) != address(0)) {
            SafeTransferLib.safeApprove(_cup, address(feeRouter), type(uint256).max);
        }
        emit CupTokenSet(_cup);
    }

    // ── Pool creation (factory) ──────────────────────────────────────────

    /// @inheritdoc ITeamMarket
    /// @dev Factory-only. Pulls `tokenAmount` team tokens from the caller as
    ///      the curve's Y reserve. `tier` is the tier RANK (S=3..MEME=0).
    function createPool(bytes32 teamId, address token, uint8 tier, uint128 virtualCup, uint256 tokenAmount)
        external
        onlyRoles(FACTORY_ROLE)
    {
        if (token == address(0)) revert ZeroAddress();
        if (_pools[teamId].token != address(0)) revert PoolExists();
        if (tokenAmount == 0 || virtualCup == 0) revert ZeroAmount();

        SafeTransferLib.safeTransferFrom(token, msg.sender, address(this), tokenAmount);
        _pools[teamId] = Pool({
            token: token,
            tier: tier,
            active: false,
            virtualCup: virtualCup,
            realCup: 0,
            realTok: tokenAmount.toUint128()
        });
        emit PoolCreated(teamId, token, tier, virtualCup, tokenAmount);
    }

    // ── Swaps ────────────────────────────────────────────────────────────

    /// @inheritdoc ITeamMarket
    /// @dev Buy team tokens with CUP. Fee = ceil(cupIn * buyFeeBps / 1e4) is
    ///      routed via MARKET_BUY; tokensOut = floor against the curve.
    function buy(bytes32 teamId, uint256 cupIn, uint256 minOut, uint256 deadline)
        external
        nonReentrant
        returns (uint256 tokensOut)
    {
        if (block.timestamp > deadline) revert DeadlinePassed();
        if (paused) revert MarketPaused();
        if (cup == address(0)) revert CupNotSet();
        Pool storage pool = _pools[teamId];
        if (pool.token == address(0)) revert PoolMissing();
        if (!pool.active) revert PoolInactive();

        uint256 fee;
        (tokensOut, fee) = LibCurve.quoteBuy(pool.virtualCup, pool.realCup, pool.realTok, cupIn, buyFeeBps);
        if (tokensOut < minOut || tokensOut == 0) revert SlippageExceeded();

        // Effects before interactions: reserves reflect the net flow.
        SafeTransferLib.safeTransferFrom(cup, msg.sender, address(this), cupIn);
        pool.realCup += (cupIn - fee).toUint128();
        pool.realTok -= tokensOut.toUint128();

        // Route the fee (external; router is approved to pull from us).
        if (fee > 0) feeRouter.route(MARKET_BUY, fee, teamId, address(0));

        SafeTransferLib.safeTransfer(pool.token, msg.sender, tokensOut);
        emit Bought(teamId, msg.sender, cupIn, fee, tokensOut, _spot(pool));
    }

    /// @inheritdoc ITeamMarket
    /// @dev Sell team tokens for CUP. gross = floor; solvency gate
    ///      gross <= realCup; fee = ceil on gross, routed via MARKET_SELL
    ///      (whose POOL_DONATE leg re-enters {donateCup} on THIS pool —
    ///      reserves must be written to storage before the route call).
    function sell(bytes32 teamId, uint256 tokensIn, uint256 minOut, uint256 deadline)
        external
        nonReentrant
        returns (uint256 netCup)
    {
        if (block.timestamp > deadline) revert DeadlinePassed();
        if (paused) revert MarketPaused();
        if (cup == address(0)) revert CupNotSet();
        Pool storage pool = _pools[teamId];
        if (pool.token == address(0)) revert PoolMissing();
        if (!pool.active) revert PoolInactive();

        uint256 fee;
        uint256 gross;
        (netCup, fee, gross) = LibCurve.quoteSell(pool.virtualCup, pool.realCup, pool.realTok, tokensIn, sellFeeBps);
        if (netCup < minOut || netCup == 0) revert SlippageExceeded();

        SafeTransferLib.safeTransferFrom(pool.token, msg.sender, address(this), tokensIn);
        // Storage-committed BEFORE the router call: the POOL_DONATE leg
        // re-enters donateCup(teamId) and must see post-trade reserves.
        pool.realCup -= gross.toUint128();
        pool.realTok += tokensIn.toUint128();

        if (fee > 0) feeRouter.route(MARKET_SELL, fee, teamId, address(0));

        SafeTransferLib.safeTransfer(cup, msg.sender, netCup);
        emit Sold(teamId, msg.sender, tokensIn, fee, netCup, _spot(pool));
    }

    /// @inheritdoc ITeamMarket
    /// @dev Pure buy-pressure primitive: pulls CUP from the caller straight
    ///      into `realCup` with NO tokens out. Used by pack-sale donations,
    ///      LIQ-tranche seeding and the MARKET_SELL POOL_DONATE leg.
    ///
    ///      INTENTIONALLY not nonReentrant and not pause/active-gated:
    ///      it is called by the FeeRouter from INSIDE {sell} (which holds
    ///      the reentrancy lock), it strictly adds reserves (cannot extract
    ///      value), and reward seeding must work pre-activation.
    function donateCup(bytes32 teamId, uint256 amount) external {
        if (amount == 0) revert ZeroAmount();
        if (cup == address(0)) revert CupNotSet();
        Pool storage pool = _pools[teamId];
        if (pool.token == address(0)) revert PoolMissing();
        SafeTransferLib.safeTransferFrom(cup, msg.sender, address(this), amount);
        pool.realCup += amount.toUint128();
        emit CupDonated(teamId, msg.sender, amount);
    }

    // ── Views ────────────────────────────────────────────────────────────

    /// @inheritdoc ITeamMarket
    function quoteBuy(bytes32 teamId, uint256 cupIn) external view returns (uint256 tokensOut, uint256 fee) {
        Pool storage pool = _pools[teamId];
        if (pool.token == address(0)) revert PoolMissing();
        (tokensOut, fee) = LibCurve.quoteBuy(pool.virtualCup, pool.realCup, pool.realTok, cupIn, buyFeeBps);
    }

    /// @inheritdoc ITeamMarket
    /// @dev Reverts {LibCurve.InsufficientPoolCup} exactly like {sell} would
    ///      (fresh pools with zero realCup always revert).
    function quoteSell(bytes32 teamId, uint256 tokensIn) external view returns (uint256 netCup, uint256 fee) {
        Pool storage pool = _pools[teamId];
        if (pool.token == address(0)) revert PoolMissing();
        (netCup, fee,) = LibCurve.quoteSell(pool.virtualCup, pool.realCup, pool.realTok, tokensIn, sellFeeBps);
    }

    /// @inheritdoc ITeamMarket
    function spotPrice(bytes32 teamId) external view returns (uint256) {
        Pool storage pool = _pools[teamId];
        if (pool.token == address(0)) revert PoolMissing();
        return _spot(pool);
    }

    /// @inheritdoc ITeamMarket
    function getPool(bytes32 teamId) external view returns (Pool memory) {
        return _pools[teamId];
    }

    /// @inheritdoc ITeamMarket
    function tokenOf(bytes32 teamId) external view returns (address) {
        return _pools[teamId].token;
    }

    /// @inheritdoc ITeamMarket
    function tierOf(bytes32 teamId) external view returns (uint8) {
        if (_pools[teamId].token == address(0)) revert PoolMissing();
        return _pools[teamId].tier;
    }

    // ── Admin ────────────────────────────────────────────────────────────

    /// @notice Set swap fees, both capped at MAX_FEE_BPS (10%). Owner-only
    ///         (timelock-listed post-launch).
    function setFees(uint16 _buyFeeBps, uint16 _sellFeeBps) external onlyOwner {
        if (_buyFeeBps > MAX_FEE_BPS || _sellFeeBps > MAX_FEE_BPS) revert FeeTooHigh();
        buyFeeBps = _buyFeeBps;
        sellFeeBps = _sellFeeBps;
        emit FeesSet(_buyFeeBps, _sellFeeBps);
    }

    /// @notice Wire the fee router and max-approve it to pull swap fees. The
    ///         approval is only granted once $CUP is known; if the router is
    ///         wired before {setCupToken}, the approval is (re-)granted there.
    function setFeeRouter(address _feeRouter) external onlyOwner {
        if (_feeRouter == address(0)) revert ZeroAddress();
        feeRouter = IFeeRouter(_feeRouter);
        if (cup != address(0)) SafeTransferLib.safeApprove(cup, _feeRouter, type(uint256).max);
        emit FeeRouterSet(_feeRouter);
    }

    /// @notice Pause/unpause swaps. Views, donations and pool admin stay live.
    function setPaused(bool _paused) external onlyOwnerOrRoles(OPERATOR_ROLE) {
        paused = _paused;
        emit PausedSet(_paused);
    }

    /// @notice Batch-activate/deactivate pools (launch choreography: pools
    ///         are created inactive, pre-seeded, then activated together to
    ///         soften listing snipes).
    function batchSetActive(bytes32[] calldata teamIds, bool active) external onlyOwnerOrRoles(OPERATOR_ROLE) {
        for (uint256 i; i < teamIds.length; ++i) {
            if (_pools[teamIds[i]].token == address(0)) revert PoolMissing();
            _pools[teamIds[i]].active = active;
            emit PoolActiveSet(teamIds[i], active);
        }
    }

    /// @notice Activation pre-seed helper: donate `amounts[i]` CUP (pulled
    ///         from the caller) into each pool so pack recipients can sell
    ///         before organic buys exist.
    function preSeed(bytes32[] calldata teamIds, uint256[] calldata amounts) external {
        if (teamIds.length != amounts.length) revert ZeroAmount();
        if (cup == address(0)) revert CupNotSet();
        for (uint256 i; i < teamIds.length; ++i) {
            Pool storage pool = _pools[teamIds[i]];
            if (pool.token == address(0)) revert PoolMissing();
            SafeTransferLib.safeTransferFrom(cup, msg.sender, address(this), amounts[i]);
            pool.realCup += amounts[i].toUint128();
            emit CupDonated(teamIds[i], msg.sender, amounts[i]);
        }
    }

    /// @notice Owner-only recycling of real CUP out of a pool.
    /// @dev This is intentionally NOT operator-gated. It is a post-elimination
    ///      treasury action that reduces sell-side reserves, so it belongs behind
    ///      the proxy owner/timelock. The accounting invariant is preserved:
    ///      `pool.realCup` is debited by exactly the CUP transferred out.
    function recyclePoolCup(bytes32 teamId, uint256 amount, address to) external onlyOwner nonReentrant {
        _debitAndTransferPoolCup(teamId, amount, to);
        emit PoolCupRecycled(teamId, to, amount);
    }

    /// @notice Owner-only recycling of pool CUP into a RewardsVault team pool.
    /// @dev Moves CUP from this market to `rewardsVault` and immediately credits
    ///      `teamCupAccrued[teamId]`, so the recycled liquidity can fund the
    ///      normal Merkle emissions path via RewardsVault.fundEpochFromTeamPools.
    function recyclePoolCupToTeamPool(bytes32 teamId, uint256 amount, address rewardsVault)
        external
        onlyOwner
        nonReentrant
    {
        if (rewardsVault == address(0)) revert ZeroAddress();
        _debitAndTransferPoolCup(teamId, amount, rewardsVault);
        IRewardsVault(rewardsVault).receiveRecycledTeamPool(teamId, amount);
        emit PoolCupRecycledToTeamPool(teamId, rewardsVault, amount);
    }

    /// @notice Grant FACTORY_ROLE to the TeamTokenFactory. Owner-only.
    function setFactory(address factory) external onlyOwner {
        if (factory == address(0)) revert ZeroAddress();
        _grantRoles(factory, FACTORY_ROLE);
    }

    // ── Internals ────────────────────────────────────────────────────────

    function _spot(Pool storage pool) private view returns (uint256) {
        return LibCurve.spotPrice(pool.virtualCup, pool.realCup, pool.realTok);
    }

    function _debitAndTransferPoolCup(bytes32 teamId, uint256 amount, address to) private {
        if (amount == 0) revert ZeroAmount();
        if (to == address(0)) revert ZeroAddress();
        if (cup == address(0)) revert CupNotSet();
        Pool storage pool = _pools[teamId];
        if (pool.token == address(0)) revert PoolMissing();
        if (amount > pool.realCup) revert InsufficientPoolCup();
        pool.realCup -= amount.toUint128();
        SafeTransferLib.safeTransfer(cup, to, amount);
    }

    /// @dev UUPS authorisation gate — owner-only. NOTE: transfer ownership to a
    ///      TIMELOCK+MULTISIG before mainnet (the deploy owner is an EOA).
    function _authorizeUpgrade(address) internal override onlyOwner {}
}

