// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {FixedPointMathLib} from "solady/utils/FixedPointMathLib.sol";
import {LibFee} from "./LibFee.sol";

/// @title LibCurve
/// @notice Virtual-reserve constant-product bonding math for the nation-share
///         pools (CUP quote asset).
///
///         X = virtualCup + realCup   (CUP side, virtual reserves give P0)
///         Y = realTok                (team-token side, seeded 50M)
///
///         Buy:  fee = ceil(cupIn * feeBps / 10000) — protocol-favoured.
///               tokensOut = floor(Y * net / (X + net))
///         Sell: grossCup = floor(X * tokensIn / (Y + tokensIn))
///               SOLVENCY GATE: grossCup <= realCup. Packs/rewards put tokens
///               in circulation the curve never sold; the pool only ever pays
///               out CUP it actually received.
///               fee = ceil(grossCup * feeBps / 10000) on the gross.
///
///         Rounding is always protocol/pool-favoured (fees ceil, outputs floor).
library LibCurve {
    using FixedPointMathLib for uint256;

    /// @notice Thrown when a sell's gross CUP output exceeds the pool's real
    ///         (deposited) CUP reserves. Fresh pools with zero realCup revert
    ///         here on any sell.
    error InsufficientPoolCup();

    /// @notice Thrown when an input amount is zero.
    error ZeroAmount();

    /// @notice Thrown when the pool's token reserve would be fully drained.
    error InsufficientTokenReserve();

    /// @notice Quote a buy against the curve.
    /// @param virtualCup Virtual CUP reserve (tier-set, fixed).
    /// @param realCup    Real CUP held by the pool.
    /// @param realTok    Team-token reserve held by the pool.
    /// @param cupIn      CUP paid by the buyer (gross, fee-inclusive).
    /// @param feeBps     Buy fee in basis points.
    /// @return tokensOut Team tokens released to the buyer (floor).
    /// @return fee       CUP fee taken off the top (ceil).
    function quoteBuy(uint256 virtualCup, uint256 realCup, uint256 realTok, uint256 cupIn, uint256 feeBps)
        internal
        pure
        returns (uint256 tokensOut, uint256 fee)
    {
        if (cupIn == 0) revert ZeroAmount();
        fee = LibFee.bpsCeil(cupIn, feeBps);
        // A 1-wei buy at a non-zero fee is entirely consumed by the ceil'd
        // fee; net = 0 then tokensOut = 0 — caller's minOut protects the user.
        uint256 net = cupIn - fee;
        uint256 x = virtualCup + realCup;
        tokensOut = realTok.fullMulDiv(net, x + net);
        if (tokensOut >= realTok) revert InsufficientTokenReserve();
    }

    /// @notice Quote a sell against the curve.
    /// @param tokensIn Team tokens sold into the pool.
    /// @param feeBps   Sell fee in basis points.
    /// @return netCup  CUP paid to the seller after fee.
    /// @return fee     CUP fee (ceil on gross).
    /// @return gross   Gross CUP out before fee (floor).
    function quoteSell(uint256 virtualCup, uint256 realCup, uint256 realTok, uint256 tokensIn, uint256 feeBps)
        internal
        pure
        returns (uint256 netCup, uint256 fee, uint256 gross)
    {
        if (tokensIn == 0) revert ZeroAmount();
        uint256 x = virtualCup + realCup;
        gross = x.fullMulDiv(tokensIn, realTok + tokensIn);
        // Solvency gate — pool only pays out CUP it actually received.
        if (gross > realCup) revert InsufficientPoolCup();
        fee = LibFee.bpsCeil(gross, feeBps);
        // feeBps <= MAX_FEE_BPS (10%) in practice, but guard the 1-wei edge
        // where ceil(fee) == gross.
        netCup = gross > fee ? gross - fee : 0;
        if (netCup == 0) fee = gross;
    }

    /// @notice Marginal spot price of 1 team token in CUP, 1e18-scaled.
    function spotPrice(uint256 virtualCup, uint256 realCup, uint256 realTok) internal pure returns (uint256) {
        if (realTok == 0) return 0;
        return (virtualCup + realCup).fullMulDiv(1e18, realTok);
    }
}

