// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title ITeamMarket
/// @notice Singleton bonding-pool registry for all nation/team share tokens.
interface ITeamMarket {
    /// @notice Per-team bonding pool. `tier` is the tier RANK (S=3, A=2,
    ///         B=1, MEME=0) used by upset-multiplier and carry-weight math.
    struct Pool {
        address token;
        uint8 tier;
        bool active;
        uint128 virtualCup;
        uint128 realCup;
        uint128 realTok;
    }

    function buy(bytes32 teamId, uint256 cupIn, uint256 minOut, uint256 deadline) external returns (uint256);
    function sell(bytes32 teamId, uint256 tokensIn, uint256 minOut, uint256 deadline) external returns (uint256);
    function donateCup(bytes32 teamId, uint256 amount) external;
    function recyclePoolCup(bytes32 teamId, uint256 amount, address to) external;
    function recyclePoolCupToTeamPool(bytes32 teamId, uint256 amount, address rewardsVault) external;
    function quoteBuy(bytes32 teamId, uint256 cupIn) external view returns (uint256 tokensOut, uint256 fee);
    function quoteSell(bytes32 teamId, uint256 tokensIn) external view returns (uint256 netCup, uint256 fee);
    function spotPrice(bytes32 teamId) external view returns (uint256);
    function getPool(bytes32 teamId) external view returns (Pool memory);
    function tokenOf(bytes32 teamId) external view returns (address);
    function tierOf(bytes32 teamId) external view returns (uint8);
    function createPool(bytes32 teamId, address token, uint8 tier, uint128 virtualCup, uint256 tokenAmount) external;
}

