// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title IFeeRouter
/// @notice Single fee-routing hub. Routes are keyed bytes32; legs sum to
///         exactly 10_000 bps with dust assigned to the first leg.
interface IFeeRouter {
    enum LegKind {
        ADDRESS, // transfer CUP to `target`
        JACKPOT, // IJackpotVault(target).deposit(amount)
        TEAM_POOL, // IRewardsVault(target).creditTeam(teamId, amount)
        POOL_DONATE, // ITeamMarket(target).donateCup(teamId, amount)
        STAKING, // IStakingVault(target).notifyFeeIncome(amount)
        BURN, // cup.burn(amount)
        DYNAMIC // transfer to dynamicRecipient, fallback first JACKPOT leg target
    }

    struct Leg {
        LegKind kind;
        address target;
        uint16 bps;
    }

    /// @notice Pull `amount` CUP from msg.sender and disperse it across the
    ///         route's legs. `teamId` feeds TEAM_POOL / POOL_DONATE legs;
    ///         `dynamicRecipient` feeds DYNAMIC legs (zero → jackpot fallback).
    function route(bytes32 routeId, uint256 amount, bytes32 teamId, address dynamicRecipient) external;

    function getRoute(bytes32 routeId) external view returns (Leg[] memory);
}

