// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title IRewardsVault
/// @notice Pre-funded CUP tranche treasury + per-team reward accruals.
interface IRewardsVault {
    enum Tranche {
        GROUP, // 100M
        KO, // 100M
        JACKPOTS, // 100M
        LEADERBOARD, // 50M
