// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title LibFee
/// @notice Basis-point fee math shared by the FeeRouter, TeamMarket and games.
/// @dev All splits are exact: the sum of the returned legs always equals the
///      input amount, with rounding dust assigned to the FIRST leg.
library LibFee {
    /// @notice Denominator for all basis-point math in the protocol.
    uint256 internal constant BPS_DENOM = 10_000;

    /// @notice Thrown when a bps array does not sum to exactly {BPS_DENOM}.
    error BpsSumInvalid();

    /// @notice Thrown when asked to split with an empty legs array.
    error EmptySplit();

    /// @notice Compute `amount * bps / BPS_DENOM` rounded DOWN.
    function bpsFloor(uint256 amount, uint256 bps) internal pure returns (uint256) {
        return (amount * bps) / BPS_DENOM;
    }

    /// @notice Compute `amount * bps / BPS_DENOM` rounded UP — used for fees
    ///         so rounding always favours the protocol/pool.
    function bpsCeil(uint256 amount, uint256 bps) internal pure returns (uint256) {
        return (amount * bps + BPS_DENOM - 1) / BPS_DENOM;
    }

    /// @notice Split `amount` across `bps` legs (which MUST sum to exactly
    ///         {BPS_DENOM}). Each leg gets the floor share; accumulated
    ///         rounding dust is added to the first leg so the output always
    ///         sums to `amount` exactly — even for 1-wei inputs.
    /// @param amount Total to split.
    /// @param bps    Per-leg basis points; must sum to 10_000.
    /// @return shares Per-leg amounts; `sum(shares) == amount` exactly.
    function splitWithDustToFirst(uint256 amount, uint256[] memory bps)
        internal
        pure
        returns (uint256[] memory shares)
    {
        uint256 n = bps.length;
        if (n == 0) revert EmptySplit();
        shares = new uint256[](n);
        uint256 sumBps;
        uint256 allocated;
        for (uint256 i; i < n; ++i) {
            sumBps += bps[i];
            uint256 share = (amount * bps[i]) / BPS_DENOM;
            shares[i] = share;
            allocated += share;
        }
        if (sumBps != BPS_DENOM) revert BpsSumInvalid();
        // Dust → first leg. amount - allocated < n by construction.
        shares[0] += amount - allocated;
    }
}
